    const base = pos.length / 3, rings = [poly.outer, ...(poly.holes || [])];
    const v2 = rings.map(r => r.map(([x, z]) => new THREE.Vector2(x, z)));
    const faces = THREE.ShapeUtils.triangulateShape(v2[0], v2.slice(1));
    const flatPts = rings.flat();
